import{_ as a,c as i,o as e,af as s}from"./chunks/framework.BKeRpnBD.js";const d=JSON.parse('{"title":"周易尚氏学序言","description":"周易尚氏学 - 周易尚氏学序言","frontmatter":{"title":"周易尚氏学序言","description":"周易尚氏学 - 周易尚氏学序言"},"headers":[],"relativePath":"zh/classics/shangshi/002.md","filePath":"zh/classics/shangshi/002.md"}'),l={name:"zh/classics/shangshi/002.md"};function t(r,p,n,c,_,o){return e(),i("div",null,[...p[0]||(p[0]=[s('<h1 id="周易尚氏学序言" tabindex="-1">周易尚氏学序言 <a class="header-anchor" href="#周易尚氏学序言" aria-label="Permalink to “周易尚氏学序言”">​</a></h1><p>于省吾</p><p>易卦起源于原始宗教中巫术占验方法之一的八索之占。古也称绳为索，八索即八条绳子。金川彝族所保持的原始式八索之占，系用牛毛绳八条，掷诸地上以占吉凶。《易?系辞》称庖牺氏（即伏义氏）始作八卦，乃指八索之占言之。八索这一名称，最早见于《左传》、《国语》。八索之占是八卦的前身，八卦是八索之占的继续和发展。近年来的学者们，都说八卦与伏义氏完全无涉，这就未免「数典忘祖」，截断了易卦的来源。（详拙著《伏羲氏与八卦的关系》）原始宗教的八索之占，到了阶级社会的西周就发展为八卦；到了战国时人所作的《易传》，又以卦爻辞为基础，进一步作哲学理论的推阐。《易?系辞传》说：「刚柔相摩，八卦相荡」；「日新之谓盛德，生生之谓易」；「易之为书也不可远，为道也屡迁，变动不居，周流六虚，上下无常，刚柔相易，不可为典要，唯变所适」；「易穷则变，变则通，通则久」。由此可见，作者认为宇宙间的万事万物都处于不断运动、变化和矛盾交互的过程中，诚然具有辩证法的因素。但是，总的说来，还脱离不了否泰、剥复和消息盈虚之说。例如《蛊?彖传》所说的「终则有始」，《系辞传》所说的「原始反终」，仍然是循环论者的论调。</p><p>左昭二年传叙韩宣子适鲁，「见《易象》与《鲁春秋》」。其称《易》为《易象》，足征《易》之为书是以象为主的。《易?系辞传》也说：「是故易者象也，象也者像也。」因为辞由象生，故《易》无象外之辞。《周易》的每一卦辞和每一爻辞，往往在几句话里有几种不同的内容，假若不依象以释辞，则奇奇怪怪，迷离惝恍，既不知其辞之所本，更不知其义之所由生。但是，《说卦传》所叙的象颇为简略，远远概括不了易卦中各种各样的象。于是主汉易以说象者，对于不解之象，则以「卦变」、「爻变」为释，故尚先生叙清儒解《易》说：「……而以汉人为依归是矣。乃于汉人之曲说，亦靡不依据以为护符。至求象不得，亦使卦再三变以成其象，奉虞氏为不刊法则，而易学遂故步自封矣。」（见《焦氏易诂凡例》）</p><p>魏晋以前之说《易》者都主象，自王辅嗣扫象不谈，专以承乘比应为解，历唐至宋，便极盛一时。尚先生说：「王辅嗣深知其谬，而不能求得其象，乃倡为得意忘象之说，以掩其短，此端一开，程伊川遂谓得其义则象数在其中，本未颠倒。」（见《焦氏易诂凡例》）这是说程氏不能依象数以解卦爻辞，全凭主观臆想以为之说，反而说象数在臆想之中，这样倒末为本，是极其荒谬的。</p><p>先生钻研《焦氏易林》十余年，着《焦氏易林注》十六卷，参考各家诂训，反复推勘，积疑生悟，因而在《易林》中发现了久已失传而与《周易》有关的内外卦象、互象、对象、正反象、半象、大象等凡百二十余象的应用规律。验之于《左传》、《国语》的占象而合，验之于《逸周书?时训》的准象而合，验之于《周易》卦象也都基本上相合。先生以《易林》逸象与《周易》交融互证，分条加以阐发，着《焦氏易诂》十一卷。今就此书节录三条于下：</p><ul><li><p>一、干日：《易林》「干之泰云，白日皎皎，泰下干，干为日，互震为白，故曰皎皎。又泰之恒云，踰日历月，恒互兑为月，干为日，故曰踰日历月，是《易林》显以干为日也。后思易干九三云，君子终日干干，干为日，三居卦末，故日终日。大畜九三云，日闲舆卫，日亦指干。」（卷一）</p></li><li><p>二、兑月：「《易林》复之临云，月出平地，坤为地，兑为月，在下故曰平地。又晋之小过云，月出阜东，小过民为阜，互兑为月，震为东，故月出阜东。……后思易小畜之月几望，中孚、归妹之月几望，恒彖之日月得天久照，盖皆以兑为月，故《易林》用之，邵子亦用之也。」（卷一）</p></li><li><p>三、坤水：《易林》「干之观云，江河淮海，天之奥府。按观下重坤，故曰江河淮海，又坤之升云，凭河登山，升上坤，坤水，故曰凭河。又讼之泰，弱水之西，坤水、坤柔，故曰弱水。」（卷一）「凡易言利往、利涉者，义无不通。特坤水象至东汉失传，必以坎为大川，遂尔歧误，而解益之大川尤扞格难通。」（卷五「益、利有攸往利涉大川解」。按「川」字原本误作「利」）</p></li></ul><p>以上所引三条，用《易林》干日、兑月、坤水之象，与《周易》相证发，六通四辟，若合符契。学者只知离为日，坎为月为水，则多与卦象不相应。先生以《焦氏易诂》为基础（读本书者，须参阅《焦氏易林注》、《焦氏易诂》、《左传国语易象释》三书），对于历来的易象和易解，广搜博采，评判其得失，取长舍短；同时，又结合其师吴挚甫《易说》的「阳遇阴则通、遇阳则阻」的原理（见本书「说例」）而加以发展，谓「易之道如电然，同性则相违，异性则相感」（见《易诂》「同人、利涉大川解」），着《周易尚氏学》二十卷。于是久已晦盲的易象，始昭然若揭，可谓发幽阐微，集象学之大成。《焦氏易林注》仵墉叙引王晋卿说：「此书将二千年易家之盲词呓说，一一驳倒，使西汉易学复明于世，孟子所谓其功不在禹下。」又引陈散原说：「读尚氏《焦氏易诂》，叹为千古绝作。以今世竟有此人着此绝无仅有之书，本朝诸儒见之当有愧色。」</p><p>以上所述，主要是说明先生对易象的卓越发明。但是，本书也还存在着某些缺点和错误，例如：</p><ul><li><p>一、关《周易》作者的问题，先生对于书卦者以及卦爻辞、《易传》的作者，多因袭旧说。在本书「总论」中「第三论古易之类别」说：「伏义既画卦，必更有书以申明其义。……后人谓黄帝始造字，伏义祇画卦无文字者，谬也」；「第四论周易谁作」说：「……故夫《周易》卦爻辞，纯为文王一人所作，其欲加入周公者，毫无根据，不可信也」；「第六论十翼谁作」说：「…… 故《十翼》非孔子不能为，不敢为，而纪录《十翼》者，则孔子之门人也」。像以上各种肯定的说法，都脱离不了旧有圈套。先生对于近年来学者们的若干新说，一概置之不理。纵然他们对于旧解有着一笔抹杀的过分主张，未可尽信，可是，伏羲氏既画卦又重卦，以及文王作卦爻辞，孔子作《十翼》等传统说法，毕竟是靠不住的。</p></li><li><p>二、震象为丘 《说文》谓「四方高中央下为丘」，《淮南子?坠形》的「和丘」，高注谓「四方而高曰丘」。按震作◇，象四方高中央下之形。丘字卜辞作◇，金文作◇，以卦画有横无竖验之，则古文字的丘字正与震象相符洽。《易林》革之颐说：「尼父孔丘」；（尚先生谓反震为孔），颐下震为丘，故曰「尼父孔丘」；又屯之噬嗑说：「营邱（同丘）是适」，噬嗑下震为丘（尚先生谓「震往故日适」），故曰「营邱是适」。这都是《易林》以震为丘之证。以震为丘，于《周易》中之言丘者无一不合。贲卦作◇，六五：「贲于丘园」，丘园指「上互」为震言之；颐卦作◇，六二：「拂经于丘」，丘指内卦为震言之；涣卦作◇，六四：「涣有丘」，丘指涣「下互」为震言之。丘与◆古通用。古人多居丘。《说文》谓「◆、大丘也」，又谓「四邑为丘，丘谓之◆」。升卦作◇，九三：「升◆邑」，马注谓「◆、丘也」。丘邑指「上互」为震言之。总之，《周易》中言丘者三见，言◆者一见，都取象于震。而先生有的谓艮为山以当丘，有的训丘为空，又以巽为◆，既不能一以贯之，又均背于易象。此外，鼎卦作◇，《干凿度》谓「鼎象以器」。毛奇龄《仲氏易》说：「鼎有足有腹有耳有铉，而卦文俱象之。下画偶似足，二三四画奇皆中实，似腹，五画偶似耳，上画奇似铉。」按毛解甚确，而先生于本书从端木国瑚之说，谓「鼎之象不在鼎，而在伏象屯」，舍鼎形之实象而信伏象，未免疏失。</p></li><li><p>三、训诂和史实 《说卦传》以坎为月，先生据《易林》逸象以兑为月，用以解易，无一不通。但是，为什么以兑为月，则未加说明。按《说文》：「月、阙也」，《释名?释天》：「月、阙也，满则阙也」，是月、阙迭韵，以音为训。再就形言之，古文字月作◇或◇，正像月阙形。兑上偶画中阙，故以兑为月（其它卦象，与文字形或音有关系者，在此不加详论）。小过六二：「过其祖，遇其妣」，先生误从《尔雅?释亲》「母曰妣」以为之解。按妣为祖母，《诗?斯干》的「似续妣祖」，《丰年》的「烝畀祖妣」，均以祖与妣对称。《周礼?大司乐》「以享先妣」与「以享先祖」，相偶为文。卜辞和金文均称祖母为妣，从无以妣为母者。以妣为母，始见于战国末期的典籍，与易辞不符。否九五：「其亡其亡，系于苞桑」，陆续训苞桑为丛桑，甚是。不言系于桑而言系于丛桑，自系就巩固为言。而先生谓「桑而丛生，其柔可知，系于柔木，其危可知」，未能允当。坎六四：「樽酒簋贰用缶，纳约自牖」，约为勺的借字，即酌酒之斗。《考工记》郑注谓「勺、故书或作约」，是其证。《诗?采苹》：「于以奠之，宗室牖下」，是古奠祭于牖下之证。「纳勺自牖」，是说祭时自牖纳勺于樽以挹酒。而先生引《周礼?司约》的「治神之约」以为之解，乖于本义。《晋卦辞》：「康侯用锡马蕃庶」，康侯即《书?康诰》的康叔封，金文作「康侯丰」。而先生误谓「康侯略如大侯，为诸侯之美称」。益六四：「利用为依迁国」，依应读作殷，即《书序》所说的「成周既成，迁殷顽民」。而先生误据《说文》训依为倚。升六四：「王用享于歧山」，先生谓「纣</p></li></ul><p>能囚文王，何不可到岐山」。其实，纣何曾到过岐山？归妹六五：「帝乙归妹，先生谓「帝乙、汤也」。其实，帝乙谓纣父，太乙何曾有帝乙之称？</p><p>总起来说，先生的主要成就是通过对《焦氏易林》的多年钻研，在极为错综复杂的情况下，用归纳方法，分析和总结了各种逸象的应用规律，进一步以之诠释《周易》，基本上都是吻合无间的。因此，《左传》、《国语》、《易林》和《易卦》的用象，才由前此的对立得到统一。由于《周易》无象外之辞。而先生的绝大发明则在乎象，解决了旧所不解的不可胜数的易象问题，可以说，先生对易象的贡献是空前的。但是，也无可讳言，先生对《周易》的作者，只沿袭传统旧说；并且，对某些卦象，以及文字、声韵、训诂和史实方面，仍有许多可议之处。不过，前者的若干发明是主要的，后者的某些缺点和错误是次要的。由于是非得失系客观存在，不以个人爱憎为转移，有关本书的某些缺点和错误，与其使读者劳神笔墨，一一加以指责，不如先事择要说明之为愈。因此，本文不敢阿其所好，为先生回短护非，遂不自量地举出一些事例，评论其得失（当然限于篇幅，很不全面）。庶几瑕不掩瑜，晶光赫露，而先生的苦心孤诣和一系列的发明，也可以信今而传后了。</p><p>一九六三年四月于长春</p><p>(注：文中有些卦画或符号无法打出，以◇代替。另文中◆是古字，其字是”虎”字截去下半的”儿”而代之以”丘”)</p>',14)])])}const f=a(l,[["render",t]]);export{d as __pageData,f as default};
